import java.util.*;

class Solution {
    public boolean canBuildNote(String note, String magazine) {
        int[] cnt = new int[26];
        for (int i = 0; i < magazine.length(); i++) cnt[magazine.charAt(i) - 'a']++; // supply
        for (int i = 0; i < note.length(); i++) {
            int c = note.charAt(i) - 'a';
            cnt[c]--;                    // use one copy
            if (cnt[c] < 0) return false; // ran out of this letter
        }
        return true;
    }
}

